import{_ as h,o as i,c as a,a3 as t}from"./chunks/framework.DX_KL3e0.js";const d=JSON.parse('{"title":"Cấu Hình Tài Sản","description":"","frontmatter":{},"headers":[],"relativePath":"quan-tri/cau-hinh-tai-san.md","filePath":"quan-tri/cau-hinh-tai-san.md","lastUpdated":1782639524000}'),o={name:"quan-tri/cau-hinh-tai-san.md"};function c(l,n,r,s,u,e){return i(),a("div",null,[...n[0]||(n[0]=[t('<h1 id="cau-hinh-tai-san" tabindex="-1">Cấu Hình Tài Sản <a class="header-anchor" href="#cau-hinh-tai-san" aria-label="Permalink to &quot;Cấu Hình Tài Sản&quot;">​</a></h1><p>Trang <strong>Cấu Hình Tài Sản</strong> dùng để quản trị các danh mục nền của module tài sản và cấu hình nhắc nhở bảo trì/bảo hành.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/asset-management/admin/config</code>.</li><li><strong>Ai dùng được:</strong> Admin và Super Admin.</li><li><strong>Dùng để:</strong> quản lý loại tài sản và cấu hình người nhận nhắc bảo trì/bảo hành.</li></ul></div><h2 id="phan-1-danh-muc-loai-tai-san" tabindex="-1">Phần 1: Danh mục loại tài sản <a class="header-anchor" href="#phan-1-danh-muc-loai-tai-san" aria-label="Permalink to &quot;Phần 1: Danh mục loại tài sản&quot;">​</a></h2><p>Tại đây bạn có thể:</p><ul><li>tạo loại tài sản mới</li><li>sửa tên hoặc quy ước loại tài sản</li><li>ẩn hoặc xóa loại tài sản không còn dùng</li></ul><p>Danh mục này ảnh hưởng trực tiếp tới các màn hình tạo/sửa tài sản trong module <strong>Quản lý Tài Sản</strong>.</p><h3 id="khi-nao-nen-tao-loai-moi" tabindex="-1">Khi nào nên tạo loại mới <a class="header-anchor" href="#khi-nao-nen-tao-loai-moi" aria-label="Permalink to &quot;Khi nào nên tạo loại mới&quot;">​</a></h3><p>Chỉ tạo loại mới khi:</p><ul><li>phát sinh một nhóm tài sản thực sự khác về nghiệp vụ quản lý</li><li>cần tách lọc, báo cáo hoặc nhắc bảo trì riêng</li></ul><p>Không nên tạo quá nhiều loại trùng nghĩa vì sẽ làm dữ liệu khó dùng về sau.</p><h2 id="phan-2-nhac-bao-tri-bao-hanh" tabindex="-1">Phần 2: Nhắc bảo trì / bảo hành <a class="header-anchor" href="#phan-2-nhac-bao-tri-bao-hanh" aria-label="Permalink to &quot;Phần 2: Nhắc bảo trì / bảo hành&quot;">​</a></h2><p>Khu vực này dùng để cấu hình:</p><ul><li>loại nhắc liên quan tài sản</li><li>người nhận nhắc nhở</li><li>phạm vi áp dụng cho tài sản không có người dùng trực tiếp</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Nên rà soát danh sách người nhận định kỳ để tránh tình trạng có nhắc việc nhưng không còn ai chịu trách nhiệm theo dõi.</p></div><h2 id="quy-tac-quyen" tabindex="-1">Quy tắc quyền <a class="header-anchor" href="#quy-tac-quyen" aria-label="Permalink to &quot;Quy tắc quyền&quot;">​</a></h2><ul><li><strong>Admin</strong> có thể vận hành cấu hình tài sản.</li><li><strong>Super Admin</strong> có quyền cao hơn với phần người nhận nhắc nhở.</li><li>Người dùng thường sẽ không vào được trang này.</li></ul><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Sửa cấu hình ở đây có ảnh hưởng ngay không?</strong><br> Có. Danh mục và người nhận nhắc nhở thường tác động trực tiếp đến các màn hình nhập liệu và luồng nhắc việc.</p><p><strong>Vì sao tôi vào trang nhưng chỉ thấy thông báo không có quyền?</strong><br> Tài khoản của bạn không phải Admin hoặc Super Admin.</p><hr><p><em>Liên quan:</em> <a href="/help/chuc-nang/tai-san.html">Quản lý Tài Sản</a></p>',22)])])}const p=h(o,[["render",c]]);export{d as __pageData,p as default};
